"""docich#4683: the roster row must match even without an exact parse.

Live ch1/ch2 runs opened the main menu 90 times and the scan still never left
open_menu: an exact word match on しょうぐん can fail on a trailing space or a
suffix, and every miss pressed down until the give-up bound.
"""
from docich.hanjuku_speedrun.hanjuku.flows import post_month_status as post
from docich.hanjuku_speedrun.hanjuku.os_layer.screen import Screen


def memory():
    mem = {'chapter': 1, 'month': '1-2', 'tick': 10, '_records': []}
    post.arm(mem)
    return mem


def test_the_scan_asks_the_roster_row_by_prefix(monkeypatch):
    calls = []

    def fake_menu_to(screen, label, **kw):
        calls.append((label, kw))
        return 'here'

    monkeypatch.setattr(post, 'menu_to', fake_menu_to)
    mem = memory()
    state = mem['post_month_status']
    state.update(stage='open_menu', phase_reads=3)
    menu = Screen([], (146, 49, 164, 62), 'ステータス しょうぐん', kind='main_menu')
    assert post.step(menu, mem, None) == [post.pad('a')]
    assert calls and calls[0][0] == 'しょうぐん'
    assert calls[0][1].get('exact') is False
    assert mem['post_month_status']['stage'] == 'roster'
